// ── KB coverage + card lint (verified against surviving cards) ──
// v15.17: chunk identity comes from the caller, never from a model-authored heading.
function parseKBCoverage(text,chunk=1){
  const refs=[];
  for(const raw of String(text||'').split('\n')){
    const ids=[...raw.matchAll(/\bfact-\d+\b/gi)].map(m=>m[0].toLowerCase());if(!ids.length)continue;
    const destinations=[...raw.matchAll(/(?:#\s*|\bline\s+)(-?\d+)(?=$|[ \t,])/gi)];
    const line=destinations.length===1?Number(destinations[0][1]):NaN;
    for(const id of ids)refs.push({id,chunk,line});
  }
  return refs;
