// v16.0: capture the aliases and subtype actually available to generation for later source review.
function ankiSourceSnapshot(kb){
  const facts=[];
  for(const condition of (kb&&kb.conditions)||[])for(const f of condition.facts||[])facts.push(Object.freeze({
    id:String(f.id||'').toLowerCase(),condition:condition.name||'',aliases:Object.freeze((condition.aliases||[]).map(a=>String(a))),subtype:String(f.subtype||''),text:String(f.text||''),sourceQuote:String(f.sourceQuote||''),tier:f.tier,bucket:f.latteBucket,
    sources:Object.freeze((f.sources||[]).map(p=>Object.freeze({filename:String(p.filename||''),location:String(p.location||'')})))
  }));
  const byId=Object.create(null);for(const f of facts)byId[f.id]=f;
  return Object.freeze({facts:Object.freeze(facts),byId:Object.freeze(byId)});
