function ankiChunkFactIds(text){return [...new Set([...String(text||'').matchAll(/^FACT\s+(fact-\d+)\s*\|/gim)].map(m=>m[1].toLowerCase()))];}
// v16.0: diagnose missing IDs and contradictory/repeated edges without discarding valid many-to-many support.
function attachCoverageToCards(cards,ledgers,snapshot,chunkIds){
  const byLine=new Map(cards.map(c=>[c.chunk+':'+c.sourceLine,c])),issues=[],declared=new Set(),edges=new Set(),destinations=new Map();
  const addIssue=(ref,code,card)=>{const issue={...ref,code};issues.push(issue);if(card)card.mappingIssues.push(issue);return issue;};
  for(const card of cards){card.factIds=[];card.mappingIssues=[];}
  for(const ledger of ledgers)for(const ref of parseKBCoverage(ledger.text,ledger.chunk)){
    const card=byLine.get(ref.chunk+':'+ref.line),key=ref.chunk+':'+ref.id;
    const identityCode=!snapshot.byId[ref.id]?'unknown-id':!(chunkIds[ref.chunk-1]||[]).includes(ref.id)?'out-of-chunk':null;
    if(identityCode){addIssue(ref,identityCode,card);continue;}
    declared.add(key);
    if(!Number.isSafeInteger(ref.line)||ref.line<0||ref.line>0&&!card){addIssue(ref,'invalid-destination',card);continue;}
    const edge=key+':'+ref.line;
    if(edges.has(edge)){addIssue(ref,'duplicate-edge',card);continue;}
    edges.add(edge);
    if(!destinations.has(key))destinations.set(key,{id:ref.id,chunk:ref.chunk,lines:new Set()});
    destinations.get(key).lines.add(ref.line);
    if(ref.line===0){addIssue(ref,'omitted');continue;}
    if(!card.factIds.includes(ref.id))card.factIds.push(ref.id);
  }
  for(const dest of destinations.values())if(dest.lines.has(0)&&dest.lines.size>1){
    const issue=addIssue({id:dest.id,chunk:dest.chunk,line:0},'conflicting-omission');
    for(const line of dest.lines)if(line>0)byLine.get(dest.chunk+':'+line).mappingIssues.push(issue);
  }
  for(let i=0;i<chunkIds.length;i++)for(const id of new Set(chunkIds[i]||[]))if(!declared.has((i+1)+':'+id))addIssue({id,chunk:i+1},'missing-id');
  for(const card of cards)if(!card.factIds.length)issues.push({code:'no-mapping',noteId:card.id,chunk:card.chunk,line:card.sourceLine});
