// v15.17: only equivalent valid Text, Extra, effective tags and keep choices may merge sources.
function ankiDedupeCards(cards){
  const seen=new Map(),out=[];
  for(const original of cards){
    const c={...original,factIds:[...(original.factIds||[])],mappingIssues:[...(original.mappingIssues||[])]};
    const key=lintAnkiCard(c).length?null:JSON.stringify([String(c.text||''),String(c.extra||''),[...new Set(String(c.tags||'').trim().split(/\s+/))].sort(),!!c.keep]);
    if(key&&seen.has(key)){const kept=seen.get(key);kept.factIds=[...new Set([...kept.factIds,...c.factIds])];kept.mappingIssues.push(...c.mappingIssues);continue;}
    if(key)seen.set(key,c);out.push(c);
