// v15.17: retain partial responses for private replay without retaining credentials or
// publishing interrupted notes. Aggregate diagnostics alone would hide cancellation defects.
function ankiRunEvidence(run,status){return {status,model:run.model,thinkingLevel:run.thinkingLevel,context:run.context,snapshot:run.snapshot,chunkIds:run.chunkIds||[],rawResponses:[...run.rawResponses],partialResponse:run.partialResponse||'',truncated:!!run.truncated};}
function ankiRunIsCurrent(run,active,sourceKB){return run===active&&run.sourceKB===sourceKB&&!run.ctl.signal.aborted;}
function ankiLinkedIds(card,snapshot){return (card.factIds||[]).filter(id=>snapshot&&snapshot.byId[id]);}
// v16.2: normalize only proven source aliases; semantic topic choices and ambiguous mappings stay reviewable.
function ankiConditionTagKey(value){
  if(typeof value!=='string'||value.length>512||/[\p{Cf}\p{Cs}]/u.test(value))return '';
  return value.normalize('NFC').replace(/[^\p{L}\p{N}\p{M}]/gu,'').toLowerCase().normalize('NFC');
