  const words=value.normalize('NFC').replace(/['\u2018\u2019]/g,'').match(/[\p{L}\p{N}][\p{L}\p{N}\p{M}]*/gu)||[];
  const slug=words.map(w=>{const chars=Array.from(w);return chars[0].toUpperCase()+chars.slice(1).join('');}).join('');
