function ankiConditionTagIndex(snapshot){
  const index={snapshot,valid:!!snapshot&&Array.isArray(snapshot.facts),facts:new Map(),invalidIds:new Set(),conditions:new Map(),owners:new Map()};
  if(!index.valid)return index;
  for(const f of snapshot.facts){
    if(!f||typeof f.id!=='string'||!f.id){index.valid=false;continue;}
    if(index.facts.has(f.id))index.invalidIds.add(f.id);else index.facts.set(f.id,f);
