// v16.5: an empty edit list cannot distinguish canonical tags from a skipped repair.
// Capture every normalization decision without copying runtime fields or changing its policy.
function ankiConditionTagDiagnostic(card,check){
  const string=value=>typeof value==='string'?value:'';
