// v15.17: marker counts accepted broken/nested clozes and could expose answers in preview.
// This is the one parser for the suite's flat subset; it never repairs the user's text.
function parseAnkiClozes(value){
  const text=String(value||''),spans=[],issues=[];
  const delimiter=/\{\{|\}\}/g;let m;
