// v15.17: substring tier tags and multiple distinct tiers made badges/filter/export disagree.
// Repeated copies of one complete tier tag have one effective tier.
function ankiTier(tags){const tiers=[...new Set(String(tags||'').trim().split(/\s+/).filter(t=>/^Tier::[123]$/.test(t)))];return tiers.length===1?tiers[0].slice(-1):'?';}
