const LINT_LABEL={'no-cloze':'no {{c…}} cloze','cloze-structure':'invalid flat cloze syntax','no-tier':'requires one complete Tier::1–3 tag','many-cloze':'>3 cloze indices','tag-format':'generated tags require nonempty ::-separated names; repair stray words','pipe-format':'each field must be one line without pipes'};
