function ankiPreviewText(text,index,revealed=false){return ankiRenderClozes(parseAnkiClozes(text),index,revealed);}
// v15.17: keep records only the student's selection. Structural exclusion is derived,
// so a repair restores eligibility without ever reversing a manual exclusion.
